        s.blocks.filter(b => b.userData.isSiege).forEach(b => { s.scene.remove(b); if (b.geometry) b.geometry.dispose(); if (b.material) b.material.dispose(); });
        s.blocks = s.blocks.filter(b => !b.userData.isSiege);
