  // Phase 205: Hurricane Tracker
  const [phase205Open, setPhase205Open] = useState(false);
  const [phase205Ctrl0, setPhase205Ctrl0] = useState(3);
  const [phase205Ctrl1, setPhase205Ctrl1] = useState(1000);
  const [phase205Ctrl2, setPhase205Ctrl2] = useState(0.5);
  const [phase205Info0, setPhase205Info0] = useState('—');
  const runPhase205 = (actionKey) => {
    const s = threeRef.current;
    if (!s || !s.scene) return;
    switch(actionKey) {
      case 'track': {
        if (s._hurricane) { s.scene.remove(s._hurricane); s._hurricane.geometry.dispose(); s._hurricane.material.dispose(); s._hurricane = null; if (s._hurricaneInterval) { clearInterval(s._hurricaneInterval); s._hurricaneInterval = null; } setPhase205Info0('Stopped'); return; }
        const cat = phase205Ctrl0;
        const count = phase205Ctrl1;
        const speed = phase205Ctrl2;
        const geo = new THREE.BufferGeometry();
        const positions = new Float32Array(count * 3);
        const colors = new Float32Array(count * 3);
        const data = [];
        for (let i = 0; i < count; i++) {
          const angle = Math.random() * Math.PI * 2;
          const r = 0.5 + Math.random() * (cat * 2);
          positions[i*3] = Math.cos(angle) * r;
          positions[i*3+1] = (Math.random() - 0.5) * 2;
          positions[i*3+2] = Math.sin(angle) * r;
          const t = r / (cat * 2);
          colors[i*3] = t; colors[i*3+1] = 0.5; colors[i*3+2] = 1 - t;
          data.push({ angle, r, y: positions[i*3+1], speed: 0.02 + Math.random() * 0.03 * cat });
        }
        geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
        const mat = new THREE.PointsMaterial({ size: 0.15, vertexColors: true, transparent: true, opacity: 0.8 });
        const pts = new THREE.Points(geo, mat);
        pts.position.y = 4;
        s.scene.add(pts); s._hurricane = pts;
        s._hurricaneData = data;
        s._hurricanePos = new THREE.Vector3(0, 4, 0);
        s._hurricaneDir = new THREE.Vector3(0.02 * speed, 0, 0.01 * speed);
        setPhase205Info0('Category ' + cat + ' — tracking');
        s._hurricaneInterval = setInterval(() => {
          if (!s._hurricane) return;
          s._hurricanePos.add(s._hurricaneDir);
          if (Math.abs(s._hurricanePos.x) > 10) s._hurricaneDir.x *= -1;
          if (Math.abs(s._hurricanePos.z) > 10) s._hurricaneDir.z *= -1;
          s._hurricane.position.copy(s._hurricanePos);
          const posAttr = s._hurricane.geometry.attributes.position;
          s._hurricaneData.forEach((p, i) => {
            p.angle += p.speed;
            posAttr.setXYZ(i, Math.cos(p.angle) * p.r, p.y, Math.sin(p.angle) * p.r);
          });
          posAttr.needsUpdate = true;
        }, 33);
        break;
      }
      case 'stop': {
        if (s._hurricane) { s.scene.remove(s._hurricane); s._hurricane.geometry.dispose(); s._hurricane.material.dispose(); s._hurricane = null; }
        if (s._hurricaneInterval) { clearInterval(s._hurricaneInterval); s._hurricaneInterval = null; }
        setPhase205Info0('Stopped');
        break;
      }
      default:
        toast.error('Phase 205: unknown action ' + actionKey);
    }
  };

  // Phase 206: Coin Flip Probability
  const [phase206Open, setPhase206Open] = useState(false);
