        s.blocks = s.blocks.filter(b => !b.userData.isMicroscope);
        const scales = [
          { name: '1m — Human', geo: () => new THREE.CapsuleGeometry(0.5, 1.5, 4, 8), color: 0xffdbac, count: 1, size: 1 },
          { name: '10cm — Hand', geo: () => new THREE.BoxGeometry(1, 1, 0.3), color: 0xffdbac, count: 1, size: 1 },
          { name: '1cm — Insect', geo: () => new THREE.SphereGeometry(0.3, 8, 8), color: 0x22c55e, count: 5, size: 0.5 },
          { name: '1mm — Grain of sand', geo: () => new THREE.DodecahedronGeometry(0.2), color: 0xfbbf24, count: 20, size: 0.3 },
          { name: '100µm — Dust mite', geo: () => new THREE.SphereGeometry(0.15, 6, 6), color: 0x8b4513, count: 30, size: 0.2 },
          { name: '10µm — Cell', geo: () => new THREE.SphereGeometry(0.4, 16, 16), color: 0x3b82f6, count: 8, size: 0.6 },
          { name: '1µm — Bacteria', geo: () => new THREE.CapsuleGeometry(0.1, 0.3, 4, 4), color: 0xef4444, count: 20, size: 0.4 },
          { name: '100nm — Virus', geo: () => new THREE.IcosahedronGeometry(0.3), color: 0xa855f7, count: 15, size: 0.5 },
          { name: '10nm — DNA helix', geo: () => new THREE.SphereGeometry(0.1, 6, 6), color: 0x22c55e, count: 40, size: 0.2 },
          { name: '1nm — Atom', geo: () => new THREE.SphereGeometry(0.5, 16, 16), color: 0x06b6d4, count: 5, size: 0.8 },
        ];
        const idx = Math.min(phase208Ctrl0, scales.length - 1);
