            const wGeo = new THREE.TorusGeometry(1 + i * 0.5, 0.1, 8, 32);
            const wMat = new THREE.MeshStandardMaterial({ color: new THREE.Color().setHSL(i / count, 1, 0.5), emissive: new THREE.Color().setHSL(i / count, 1, 0.5), emissiveIntensity: 0.5 });
            const w = new THREE.Mesh(wGeo, wMat);
